import { withAccessIdentity } from "@recallfeed/api/access";
import { app } from "@recallfeed/api/app";
import { configureLocalNeonHttp } from "@recallfeed/database";
// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as nextHandler } from "./.open-next/worker.js";
import type { ReflectionFeedEnv } from "./src/env";

const API_PREFIX = "/api";
const LOCAL_HOSTS = new Set(["localhost", "127.0.0.1", "[::1]"]);

/**
 * LOCAL DEVELOPMENT ONLY, through `wrangler.local.jsonc` (`pnpm preview:local`). Never deployed.
 *
 * There is no Cloudflare Access locally, so this entry treats every request as the owner: it skips
 * the token check that worker.ts performs. To keep a mistaken deployment of this file from becoming an
 * open door, it serves only requests addressed to localhost and refuses everything else. It also routes
 * the exact host `db.localtest.me` to the local database proxy, which does nothing for a real Neon URL.
 */
export default {
  async fetch(request: Request, env: ReflectionFeedEnv, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    const owner = env.OWNER_EMAIL?.trim() ?? "";
    if (!LOCAL_HOSTS.has(url.hostname) || owner === "") {
      return new Response(JSON.stringify({ error: "Local entry point", code: "LOCAL_ONLY" }), {
        status: 403,
        headers: { "Content-Type": "application/json", "Cache-Control": "private, no-store" },
      });
    }
    configureLocalNeonHttp(env.DATABASE_URL);
    const ownerCtx = withAccessIdentity(ctx, { email: owner });

    if (url.pathname === API_PREFIX || url.pathname.startsWith(`${API_PREFIX}/`)) {
      url.pathname = url.pathname.slice(API_PREFIX.length) || "/";
      return app.fetch(new Request(url, request), env, ownerCtx);
    }
    return nextHandler.fetch(request, env, ownerCtx);
  },
} satisfies ExportedHandler<ReflectionFeedEnv>;
